// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2008, "4-5", [{"author":"М. Лунёва","question":"Какое слово лишнее по смыслу?","choices":["<em>итальянка</em>","<em>мексиканка</em>","<em>россиянка</em>","<em>египтянка</em>","<em>грубиянка</em>."],"key":"Д","review":["Пять названий людей","Итальянка, мексиканка, россиянка и египтянка названы по странам, с которыми они связаны.","Слово «грубиянка» описывает поведение человека: она грубит. Страну по этому слову узнать нельзя."]},{"author":"И. Иткин","question":"Каким бывает только знак?","choices":["твёрдым","мягким","вопросительным","восклицательным","препинания."],"key":"Д","review":["Каким бывает знак","Проверь, могут ли признаки относиться к другим вещам. Бывают твёрдый камень, мягкий диван, вопросительное предложение и восклицательная интонация.","В сочетании «знак препинания» слово «препинания» указывает на назначение знака. Среди данных вариантов только оно подходит именно к слову «знак»."]},{"author":"С. Бурлак","question":"— <em>Мама! Дай мне этот огурец, он мне присмотрелся,</em> — сказал маленький Саша. А как надо было сказать?","choices":["так и надо было","<em>...он ко мне присмотрелся</em>","<em>...он меня присмотрел</em>","<em>...он мне приглянулся</em>","<em>...он мне пригляделся</em>."],"key":"Г","review":["Саша выбирает огурец","Из просьбы «дай мне этот огурец» ясно, что Саше понравился огурец. Замени детский глагол словом со значением «понравился».","«Огурец мне приглянулся» означает «он мне понравился». А «присмотрелся» значит «внимательно посмотрел»: это мог бы сделать Саша."]},{"author":"В. Черванёва","question":"В каком из этих слов не такой суффикс, как в остальных?","choices":["<em>помидорчик</em>","<em>огурчик</em>","<em>укропчик</em>","<em>бананчик</em>","<em>баклажанчик</em>."],"key":"Б","review":["Суффиксы в названиях еды","Сравни «помидор» с «помидорчиком», «укроп» с «укропчиком», «банан» с «бананчиком» и «баклажан» с «баклажанчиком». Каждый раз после основы добавляется «-чик-».","Сравни «огурец» и «огурчик»: «ц» в первом слове соответствует «ч» во втором. «Ч» входит в основу, поэтому суффикс здесь только «-ик-»."]},{"author":"И. Иткин","question":"Какое из этих слов можно понять и как существительное, и как глагол?","choices":["<em>гнём</em>","<em>днём</em>","<em>жнём</em>","<em>пнём</em>","<em>ткнём</em>."],"key":"Г","review":["Слово с двумя ролями","Прочитай «мы пнём мяч». «Пнём» отвечает на вопрос «что сделаем?» и является формой глагола «пнуть».","Теперь прочитай «гриб растёт за пнём». «Пнём» отвечает на вопрос «за чем?» и является формой существительного «пень». Написание совпало."]},{"author":"Н. Валеева и И. Рубанов","question":"Как называется круг, предназначенный для спасения утопающих?","choices":["<em>спасительный круг</em>","<em>круг спасения</em>","<em>спасательный круг</em>","<em>спасающий круг</em>","<em>спасаемый круг</em>."],"key":"В","review":["Круг на воде","Круг заранее вешают у воды, чтобы при необходимости спасти человека. Название должно передавать назначение предмета.","Как «спасательная шлюпка» и «спасательный жилет», он называется «спасательный круг». Так называют предметы, предназначенные для спасения."]},{"author":"С. Бурлак","question":"Одно слово как слышится, так и пишется. Какое?","choices":["<em>одно</em>","<em>слово</em>","<em>слышится</em>","<em>так</em>","<em>пишется</em>."],"key":"Г","review":["Как слышится слово","Произнеси «одно» и «слово» в обычном темпе: одно из написанных «о» в каждом слове без ударения слышится иначе. В «слышится» и «пишется» буквы «тс» сливаются в звук [ц].","Медленно произнеси «так». Слышны [т], [а] и [к], и каждая буква передаёт соответствующий звук."]},{"author":"Е. Муравенко","question":"В каком из ребусов зашифровано не то слово, что в остальных четырёх?","choices":["ЗАНАВЕС","ЗАНАВЕС","ЗАНАВЕС","ЗАВЕСА","ЗАНАВЕС."],"key":"Г","review":["Пять ребусов","В ребусе Б прочитай «за» над буквой «в» как «за на в». Запятая перед лесом велит убрать «л»: остаётся «ес». Получается «занавес».","В ребусе Г буква «е» стоит за «в»: читай «за в е». У осы запятая убирает «о», остаётся «са». Получается «завеса»."],"figure":{"options":[{"src":"assets/medvezhonok/2008/4-5-8-1.webp","width":102,"height":51,"pixelWidth":102,"pixelHeight":51,"description":"Н перед А, маленькая с внутри е"},{"src":"assets/medvezhonok/2008/4-5-8-2.webp","width":98,"height":60,"pixelWidth":98,"pixelHeight":60,"description":"Буквы ЗА над В, затем запятая и лес"},{"src":"assets/medvezhonok/2008/4-5-8-3.webp","width":100,"height":60,"pixelWidth":100,"pixelHeight":60,"description":"Ваза с двумя запятыми перед ней, затем буквы ес над В"},{"src":"assets/medvezhonok/2008/4-5-8-4.webp","width":84,"height":58,"pixelWidth":84,"pixelHeight":58,"description":"Е за В, затем оса с запятой перед ней"},{"src":"assets/medvezhonok/2008/4-5-8-5.webp","width":204,"height":75,"pixelWidth":204,"pixelHeight":75,"description":"Зонт с заменой О на А и запятой после него, А внутри е, затем нота си с запятой после неё"}],"onlyPictures":true}},{"author":"Н. Валеева","question":"Как <strong>не</strong> может вести себя человек?","choices":["<em>обезьянничать</em>","<em>попугайничать</em>","<em>петушиться</em>","<em>змеиться</em>","<em>свинячить</em>."],"key":"Г","review":["Повадки в речи","Человек может передразнивать, повторять за другими, задираться и неряшливо вести себя. Для этого говорят «обезьянничать», «попугайничать», «петушиться» и «свинячить».","«Змеиться» значит тянуться изгибами, как змея. Так можно сказать о тропинке или реке, а среди названий человеческого поведения это слово лишнее."]},{"author":"Н. Добрушина","question":"Дано предложение в орфографии, которая была принята в России до 1918 года:\n<em>По дорогѣ не случилось никакихъ событій.</em>\nСколько вы видите отличий от того, как пишется это предложение сегодня?","choices":["одно","два","три","четыре","пять."],"key":"В","review":["Орфография до 1918 года","Запиши фразу современными буквами: «По дороге не случилось никаких событий». Теперь смотри только на различия в написании.","В «дорогѣ» буква ѣ стала «е», в «никакихъ» исчез конечный «ъ», в «событій» буква і стала «и». Это три отличия."]},{"author":"О. Шеманаева","question":"<em>... участок, ... шар, ... цвет, ... вал.</em>","choices":["<em>земной, земляной, землистый, земельный</em>","<em>земельный, земной, землистый, земляной</em>","<em>земляной, земной, землистый, земельный</em>","<em>землистый, земляной, земельный, земной</em>","<em>земельный, земляной, землистый, земной</em>."],"key":"Б","review":["Слова от земли","Планету Землю называют земным шаром, а бледный серо-бурый оттенок называют землистым цветом. Эти две пары сразу сужают выбор.","Участок земли — земельный участок. Вал, насыпанный из земли, — земляной вал. Запиши все четыре слова в порядке пропусков."]},{"author":"О. Шеманаева","question":"Перед вами — строчки из басни И. А. Крылова «Стрекоза и муравей».\nНе оставь меня, кум милый!\nДай ты мне собраться с силой\nИ до вешних только дней\nПрокорми и обогрей!\nА что такое <em>вешние</em>?","choices":["‘вечные’","‘весёлые’","‘весенние’","‘сытые’","‘тёплые’."],"key":"В","review":["Просьба стрекозы","Вспомни, почему стрекозе понадобилась помощь: наступает холодное время, а запасов у неё нет.","Она просит кормить и греть её до весны. Слово «вешние» здесь означает «весенние», как в сочетании «вешние воды»."]},{"author":"Н. Добрушина","question":"Айшат называет селение, в котором она родилась, Арчиб. Её бабушка называла его Арчи. Какое из следующих предложений взято из письма бабушки?","choices":["<em>Кроме арчибского языка, я знаю русский.</em>","<em>Он сам арчибец, арчибский язык для него родной.</em>","<em>Арчинцы — очень гостеприимные люди.</em>","<em>У арчибского языка раньше не было письменности.</em>","<em>Я по матери аварка, а по отцу арчибка.</em>"],"key":"В","review":["Айшат и её бабушка","Названия жителей и языка сохраняют часть названия селения. Айшат говорит «Арчиб», поэтому в её словах слышится «арчиб-».","В слове «арчинцы» основы «арчиб-» нет. Такое название связано с «Арчи», как говорила бабушка."]},{"author":"М. Лунёва","question":"Как называют человека, непохожего на других?","choices":["<em>жёлтая ворона</em>","<em>серая ворона</em>","<em>белая ворона</em>","<em>красная ворона</em>","<em>зелёная ворона</em>."],"key":"В","review":["Ворона среди других","Представь ворону необычной окраски в стае обычных ворон. Крылатое выражение переносит этот образ на человека, который выделяется среди других.","Скажи «Он в этой компании белая ворона». Цвет в этом устойчивом выражении — белый."]},{"author":"И. Иткин","question":"— Я знаю слово, в котором букв больше, чем слогов! — сказал Андрей.\n— Я знаю слово, в котором букв столько же, сколько слогов! — сказал Боря.\n— Я знаю слово, в котором букв меньше, чем слогов! — сказал Витя.\nКто из ребят точно неправ?","choices":["только Андрей","только Боря","только Витя","только Боря и Витя","все трое могут быть правы."],"key":"В","review":["Слоги и буквы","В слове «дом» три буквы и один слог, а в слове «я» одна буква и один слог. Примеры подтверждают слова Андрея и Бори.","В каждом слоге есть гласный звук, и для каждого такого звука в обычном русском слове нужна гласная буква. Слогов больше, чем всех букв, быть не может. Ошибается Витя."]},{"author":"О. Шеманаева","question":"Перед вами четыре отрывка из «Денискиных рассказов» В. Ю. Драгунского:\n(1) — Ну, хочешь, я дам тебе плавательный круг?\n— Я говорю: — Он у тебя <strong>лопнутый</strong>.\n(2) А у нас жила собака Дымка. У неё хвост <strong>загнутый</strong> и лохматый, и на ногах шерстяные галифе.\n(3) Мы положили Ксеньку в <strong>выдвинутый</strong> ящик от комода, и она там лежала спокойно.\n(4) — Ну что ж, пристегни его к своей юбке. Пусть он ходит за тобой <strong>пристёгнутый</strong>.\nВ каких отрывках выделенные слова неправильны с точки зрения литературного языка?","choices":["в первом и втором","только в первом","только во втором","только в третьем","только в четвертом."],"key":"Б","review":["Слова Дениски","Формы «загнутый», «выдвинутый», «пристёгнутый» называют результат действий «загнули», «выдвинули», «пристегнули». С предметами в рассказах они сочетаются.","Круг сам лопнул: по литературной норме он «лопнувший». Детскую форму «лопнутый» нужно исправить только в первом отрывке."]},{"author":"Б. Иомдин","question":"Какое из этих слов не однокоренное с остальными?","choices":["<em>землемер</em>","<em>костюмер</em>","<em>водомерка</em>","<em>примерка</em>","<em>измерение</em>."],"key":"Б","review":["Слова с похожими корнями","Землемер мерит землю, водомерка как будто мерит поверхность воды своими шагами, при примерке сверяют размер, а измерение — само действие.","Костюмер работает с костюмами. В слове «костюмер» часть «-ер» обозначает профессию, а корень «костюм-» не связан со словом «мера»."]},{"author":"Б. Иомдин","question":"В романе Ф. М. Достоевского «<em>Преступление и наказание» читаем: «Вот мои</em> <em>две комнаты. За дверью помещается моя хозяйка, госпожа Ресслих</em>». Что здесь означает вторая фраза?","choices":["‘за дверью сейчас находится хозяйка’","‘хозяйка устраивается за дверью’","‘хозяйке хватает места за дверью’","‘за дверью располагаются комнаты хозяйки’","‘за дверью ведёт дела хозяйка-помещица’."],"key":"Г","review":["Комнаты за дверью","Герой показывает, какие комнаты занимает он сам, и продолжает описывать, как устроено жильё за соседней дверью.","«Помещается» здесь значит «живёт, занимает помещение». За дверью располагаются комнаты хозяйки."]},{"author":"О. Шеманаева","question":"Каким словом нельзя закончить фразу: <em>Я не знал, что он такой…?</em>","choices":["<em>пройдоха</em>","<em>кроха</em>","<em>растеряха</em>","<em>неряха</em>","<em>пряха</em>."],"key":"Д","review":["Какой он?","Подставь «он такой пройдоха», «он такой кроха», «он такой растеряха» и «он такой неряха». Все четыре слова можно сказать о мальчике или мужчине.","Пряха — женщина, которая прядёт. Это существительное женского рода, поэтому в данной фразе с «он такой» оно не подходит."]},{"author":"О. Шеманаева","question":"Какое название хлебобулочных изделий восходит к французскому слову со значением ‘палка’?","choices":["<em>бублик</em>","<em>калач</em>","<em>батон</em>","<em>рулет</em>","<em>крендель</em>."],"key":"В","review":["Французское слово о хлебе","Представь форму изделий: бублик, калач и крендель обычно изогнуты, а рулет сворачивают; батон бывает похож на длинную палку.","Французское bâton означает «палка». По сходству формы это слово стало названием продолговатой буханки — батона."]},{"author":"С. Бурлак","question":"Антон объединял слова в пары по некоторому принципу: <em>проснуться</em> — <em>разбудить, закипеть</em> — <em>вскипятить.</em> Какое слово он нашёл в пару к слову <em>сесть</em>?","choices":["<em>сидеть</em>","<em>садиться</em>","<em>встать</em>","<em>рассесться</em>","<em>посадить</em>."],"key":"Д","review":["Слова в парах","Один человек проснулся сам, а другой мог его разбудить. Вода могла сама закипеть, а кто-то мог её вскипятить.","В паре к «сесть» нужно действие того, кто помогает или заставляет другого сесть. «Посадить ребёнка на стул» значит сделать так, чтобы ребёнок сел."]},{"author":"И. Иткин","question":"В юности А. С. Пушкин иногда подписывал свои стихи псевдонимом «<em>Александр</em> <em>Н.к.ш._.</em>». Какая буква стояла на месте пропуска?","choices":["<em>щ</em>","<em>в</em>","<em>н</em>","<em>п</em>","<em>а</em>."],"key":"Г","review":["Подпись поэта","Убери из фамилии «Пушкин» гласные «у» и «и». Останутся «П», «Ш», «К», «Н».","В подписи согласные идут с конца фамилии: «Н», «К», «Ш», «П». Место после «ш» занимает «п»."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Боря сказал: <em>хочу морожено</em>! Юля сказала: <em>хочу пирожено</em>! А как правильно?","choices":["<em>мороженое</em> и <em>пироженое</em>","<em>мороженное</em> и <em>пироженное</em>","<em>морожное</em> и <em>пирожное</em>","<em>мороженое</em> и <em>пирожное</em>","<em>мороженное</em> и <em>пироженое</em>."],"key":"Г","review":["Два десерта","Подставь привычные формы в просьбу «хочу …». О замороженном десерте говорят «мороженое», с одной «н».","Штучный десерт называют «пирожное». Сравни написания: в «мороженое» после «ж» есть «е», а в «пирожное» после «ж» сразу идёт «н»."]},{"author":"П. Аркадьев и С. Переверзева","question":"«<em>На безрыбье и карась рыба</em>», — прозвучало в одной радиопередаче. А как правильно?","choices":["<em>На безрыбье и кит рыба</em>","<em>На безрыбье и краб рыба</em>","<em>На безрыбье и ёрш рыба</em>","<em>На безрыбье и рак рыба</em>","<em>На безрыбье и уж рыба</em>."],"key":"Г","review":["Пословица о рыбе","«На безрыбье» означает «когда рыбы нет». В пословице за рыбу принимают то, что можно добыть вместо неё.","Устойчивое выражение звучит «На безрыбье и рак рыба». Рак живёт в воде, поэтому образ подходит к рыбалке."]},{"author":"К. Кноп","question":"<em>Янус</em> — первый, <em>Юнона</em> — шестой, <em>Юлий</em> — седьмой, <em>Август</em> — восьмой. Назовите имя, которому в этом списке должен соответствовать «третий».","choices":["<em>Юпитер</em>","<em>Сатурн</em>","<em>Венера</em>","<em>Марс</em>","<em>Земля</em>."],"key":"Г","review":["Числа и древние имена","Юлий напоминает об июле, седьмом месяце, а Август — об августе, восьмом. Значит, числа в списке — номера месяцев.","Третий месяц — март. Его название связано с именем римского бога Марса."]},{"author":"Б. Иомдин","question":"Вот фрагмент из сказки С. Я. Маршака «Кошкин дом» с одним пропуском:\nСвинья:\nВ пойло раньше стариков\nПятачком не лезьте.\nТут десяток пятачков,\nСколько это вместе?\nПоросята:\nАй-люли,\nАй-люли,\nТут _________ вместе!\nЧто мы пропустили?","choices":["<em>пятёрка</em>","<em>полушка</em>","<em>полтинник</em>","<em>целковый</em>","<em>пять фунтов</em>."],"key":"В","review":["Сколько пятачков?","Здесь «пятачок» может означать и поросячий нос, и монету в пять копеек. Для денежного ответа считай десяток таких монет.","Десять раз по пять — 50 копеек. Полтинником называют как раз полрубля, то есть 50 копеек."]},{"author":"А. Никулин","question":"Македонский язык — один из славянских языков. Найдите правильные переводы македонских глаголов <strong>гргори</strong>, <strong>кркори</strong>, <strong>тртори</strong>, <strong>црцори</strong>, <strong>чрчори</strong>:","choices":["<em>хрипеть</em>, <em>стрекотать</em>, <em>щебетать</em>, <em>урчать</em>, <em>тараторить</em>","<em>стрекотать</em>, <em>щебетать</em>, <em>тараторить</em>, <em>хрипеть</em>, <em>урчать</em>","<em>урчать</em>, <em>хрипеть</em>, <em>тараторить</em>, <em>стрекотать</em>, <em>щебетать</em>","<em>хрипеть</em>, <em>тараторить</em>, <em>урчать</em>, <em>щебетать</em>, <em>стрекотать</em>","<em>тараторить</em>, <em>хрипеть</em>, стрекотать, щебетать, урчать."],"key":"В","review":["Слова из Македонии","Слышно, как «тртори» напоминает «тараторить», а «чрчори» по звучанию похоже на птичье щебетание. Ищи строку, где совпадают третий и пятый переводы.","В этой строке остаются «гргори» — урчать, «кркори» — хрипеть и «црцори» — стрекотать. Прочитай их вслух: повторяющееся «цр» хорошо передаёт стрекот."]},{"author":"А. Панина","question":"Какое из следующих предложений можно понять двумя способами?","choices":["<em>Что ты видишь?</em>","<em>Что ты смотришь?</em>","<em>Что ты плачешь?</em>","<em>Что ты сердишься?</em>","Каждое из этих предложений можно понять только одним способом."],"key":"Б","review":["Двойной вопрос","В вопросах «Что ты плачешь?» и «Что ты сердишься?» слово «что» означает «почему». В вопросе «Что ты видишь?» оно называет то, что человек видит.","«Что ты смотришь?» можно спросить о предмете («Какой фильм ты смотришь?») или о причине («Почему ты смотришь?»). Оба смысла возможны."]},{"author":"О. Иншакова","question":"Вот четыре слова:\n1) <em>царство,</em> 2) <em>птица,</em> 3) <em>грустный,</em> 4) <em>город.</em>\nВ каких из них есть звук [<em>т</em>]?","choices":["только в первом, втором и третьем","только в первом","только во втором","только в первом и втором","только в первом и четвёртом"],"key":"Д","review":["Звук Т в словах","В «грустный» при обычном произношении [т] выпадает. В «птица» перед «и» слышится мягкое [т’], а буква «ц» передаёт отдельный звук [ц].","В «царство» твёрдый [т] слышен после [с]. В «город» конечная «д» оглушается до [т]: произнеси слово отдельно и послушай конец."]},{"author":"Методкомиссия","question":"<em>Чтобы сварить кофе, мама его сначала…</em>","choices":["<em>молит</em>","<em>молет</em>","<em>мелет</em>","<em>мелит</em>","ни один из вариантов (А)–(Г) не подходит."],"key":"В","review":["Как готовят кофе","Зёрна перед варкой нужно измельчить. Это действие называют «молоть кофе».","К слову «молоть» подходит ряд форм «я мелю, ты мелешь, мама мелет». Для мамы выбираем «мелет»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
